/**
 * Generate a srcSet string for a given webp image URL.
 * Based on the output of the generate_responsive_images.py script.
 * @param {string} src - The original image URL
 * @returns {string|undefined} - The generated srcSet string, or undefined if not applicable
 */
export const getResponsiveSrcSet = (src) => {
  if (!src || typeof src !== 'string') return undefined;

  // Apply to .webp images that are local (relative or pointing to our dev servers)
  if (src.endsWith('.webp')) {
    const isLocal = !src.startsWith('http') || src.includes('localhost:3000') || src.includes('localhost:8000');
    if (isLocal) {
      const baseUrl = src.substring(0, src.lastIndexOf('.webp'));
      // Updated suffixes based on disk inspection: -320, -640, -1024
      return `${baseUrl}-320.webp 320w, ${baseUrl}-640.webp 640w, ${baseUrl}-1024.webp 1024w`;
    }
  }


  
  return undefined;
};
