import { useEffect } from 'react';

const useRecaptcha = (callback) => {
  useEffect(() => {
    // Check if script already exists
    if (document.getElementById('recaptcha-script')) {
      if (typeof window.grecaptcha !== 'undefined' && callback) {
        callback();
      } else if (callback) {
        const listener = () => {
          callback();
        };
        window.addEventListener('recaptchaLoaded', listener);
        return () => window.removeEventListener('recaptchaLoaded', listener);
      }
      return;
    }

    // Create script element
    const script = document.createElement('script');
    script.src = 'https://www.google.com/recaptcha/api.js?onload=onRecaptchaLoad&render=explicit';
    script.id = 'recaptcha-script';
    script.async = true;
    script.defer = true;

    // Define the onload callback globally for Recaptcha to find
    window.onRecaptchaLoad = () => {
      console.log('Recaptcha script loaded');
      window.dispatchEvent(new Event('recaptchaLoaded'));
      if (callback) callback();
    };

    document.body.appendChild(script);

    return () => {
      // Cleanup if necessary (optional - usually scripts stay once loaded)
    };
  }, [callback]);
};

export default useRecaptcha;
